cat > /home/sbx/work/drive.py <<'EOF'
import os, pty, sys, time, json, select, pyte
# usage: drive.py '<json list of actions>'  actions: ["s", text] send, ["w", secs] wait, ["d", label] dump screen
acts = json.loads(sys.argv[1])
cols, rows = 160, 45
screen = pyte.Screen(cols, rows); stream = pyte.ByteStream(screen)
pid, fd = pty.fork()
if pid == 0:
    os.environ['TERM'] = 'xterm-256color'
    os.environ['COLUMNS'] = str(cols); os.environ['LINES'] = str(rows)
    os.execvp('rainfrog', ['rainfrog', '--url', 'sqlite:///home/sbx/work/test.db'])
import fcntl, termios, struct
fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
def pump(t):
    end = time.time() + t
    while time.time() < end:
        r, _, _ = select.select([fd], [], [], 0.05)
        if r:
            try: data = os.read(fd, 65536)
            except OSError: return
            stream.feed(data)
            # answer cursor position queries
            if b'\x1b[6n' in data: os.write(fd, b'\x1b[1;1R')
pump(3)
for a in acts:
    if a[0] == 's': os.write(fd, a[1].encode()); pump(0.6)
    elif a[0] == 'w': pump(a[1])
    elif a[0] == 'd':
        print('===== SCREEN:', a[1], '=====')
        for line in screen.display: 
            if line.strip(): print(line.rstrip())
os.write(fd, b'\x03'); pump(1)
try: os.kill(pid, 9)
except Exception: pass
EOF

